// amplify_outputs.json is generated by `ampx` (in CI, by the Amplify backend build
// phase) and is deliberately untracked. Webpack resolves it statically from
// lib/amplify.ts, so its absence breaks `next build` even when auth is switched
// off. Drop in a stub when it is missing so the app builds and runs offline;
// lib/amplify.ts detects the stub and skips Amplify.configure().
//
// A real generated file is never overwritten.
import { copyFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const clientDir = join(dirname(fileURLToPath(import.meta.url)), '..');
const target = join(clientDir, 'amplify_outputs.json');
const stub = join(clientDir, 'amplify_outputs.example.json');

if (existsSync(target)) {
  process.exit(0);
}

copyFileSync(stub, target);
console.log(
  'amplify_outputs.json not found — wrote a stub so the build can proceed.\n' +
    'Authentication is disabled against this stub. Run `npx ampx sandbox` to\n' +
    'generate a real one, or set NEXT_PUBLIC_DISABLE_AUTH=true.'
);
